import heapq
from collections import Counter

def func(nums, k):
    # Count frequency (number of lists containing each integer)
    freq = Counter()
    for lst in nums:
        freq.update(set(lst))

    # Determine order of first occurrence across lists
    seen = set()
    order = []
    for lst in nums:
        for x in lst:
            if x not in seen:
                seen.add(x)
                order.append(x)

    # Min-heap of size k, storing tuples (freq, value)
    heap = []
    for x in order:
        f = freq[x]
        if len(heap) < k:
            heapq.heappush(heap, (f, x))
        else:
            # Only replace if current frequency > smallest frequency in heap
            if f > heap[0][0]:
                heapq.heappushpop(heap, (f, x))

    # Pop all elements from heap to get the required order
    result = []
    while heap:
        result.append(heapq.heappop(heap)[1])
    return result
